def exhaustive_words():
    total=0;by=[]
    for m,G in [(F11,P11),(F23,P23)]:
        _,a=E.ungated_attempt(prepared(m,G,1,arm2),G,G,1,1,True)
        original=[q['answer']['bit'] if q['answer']['status']=='BIT' else 0 for q in a['predicate_trace']]
        L=len(original);n=0
        for e in range(3):
            for erased in itertools.combinations(range(L),e):
                bits=[None if i in erased else b for i,b in enumerate(original)]
                for t in range(3):
                    actual=list(E.enumerate_words(bits,t));want=values_ref(bits,t)
