                    n+=1
        total+=n;by.append(dict(p=m['p'],L=L,deterministic_erasure_radius_cases=n))
    return dict(cases=total,by_fixture=by,reference='all binary words of only fixed L=5,6 traces; no curve/log candidate fallback')
